"""Requisitos dos Prompts 13 a 17 na matriz mestra (Prompt 20, 02/11/2026).

O Prompt 20 repete o Prompt 11 e acrescenta à lista os Prompts 13, 14, 15, 16,
17 e 18. O P18 já estava na matriz; este módulo traz os outros cinco, lidos
inteiros em 02/11/2026. Cada prompt já tinha a própria matriz em documento
(BI_RELATORIO_TECNICO, RELATORIO_NOVAS_FUNCIONALIDADES..., RELATORIO_FINAL_DE_EVOLUCAO,
EIA_COGNITIO_*), mas sem conferência automática. Aqui cada evidência passa
pela mesma conferência do script principal.

``F("test_nome")`` procura o teste pelo nome em ``apps/*/tests`` e devolve
``caminho::test_nome``; nome inexistente vira evidência inválida e o script
reprova, como no resto da matriz.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
_INDEX = None


def F(name, app=None):
    """``caminho::name``. Nome em mais de um arquivo exige ``app`` (senão a
    evidência fica inválida e a conferência reprova)."""
    global _INDEX
    if _INDEX is None:
        _INDEX = {}
        for path in sorted((ROOT / "apps").glob("*/tests/*.py")):
            rel = path.relative_to(ROOT).as_posix()
            for line in path.read_text(encoding="utf-8").splitlines():
                s = line.strip()
                if s.startswith("def test_"):
                    _INDEX.setdefault(s[4:].split("(")[0], []).append(rel)
    files = sorted(set(_INDEX.get(name, [])))
    if app:
        files = [f for f in files if f.startswith(f"apps/{app}/")]
    if len(files) != 1:
        why = "TESTE_NAO_ENCONTRADO" if not files else "TESTE_AMBIGUO_INFORME_O_APP"
        return f"{why}.py::{name}"
    return f"{files[0]}::{name}"


